{
  "story": "K-means clusters data by assigning points to the nearest centroid and updating centroid positions until convergence.",
  "aha": {
    "stateId": "step3",
    "observation": "Centroids shift to the true center of their assigned clusters after re-evaluation."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": [
        "Init",
        "Assign",
        "Update",
        "Converge"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "K-Means Iteration",
        "regions": [
          {
            "id": "c1",
            "label": "Centroid A",
            "kind": "centroid",
            "values": ["2, 2"]
          },
          {
            "id": "c2",
            "label": "Centroid B",
            "kind": "centroid",
            "values": ["8, 8"]
          },
          {
            "id": "pts",
            "label": "Data Points",
            "kind": "points",
            "values": ["1,1", "1,2", "2,1", "9,9", "8,9", "9,8"]
          }
        ],
        "links": [
          {
            "from": "c1",
            "to": "pts",
            "label": "distance"
          }
        ],
        "states": [
          {
            "id": "step0",
            "label": "1. Initialize",
            "short": "Init",
            "sentence": "Place initial centroids randomly.",
            "why": "Starting positions anchor the algorithm.",
            "active": ["c1", "c2"],
            "calloutRegion": "c1",
            "readouts": [
              {
                "id": "r1",
                "label": "Iteration",
                "value": "0"
              }
            ]
          },
          {
            "id": "step1",
            "label": "2. Assign",
            "short": "Assign",
            "sentence": "Assign each point to the nearest centroid.",
            "why": "Forms preliminary groups based on proximity.",
            "active": ["pts"],
            "calloutRegion": "pts",
            "readouts": [
              {
                "id": "r1",
                "label": "Iteration",
                "value": "1"
              }
            ]
          },
          {
            "id": "step2",
            "label": "3. Update",
            "short": "Update",
            "sentence": "Recalculate centroids as cluster means.",
            "why": "Centroids move to balance point distribution.",
            "active": ["c1", "c2"],
            "calloutRegion": "c1",
            "readouts": [
              {
                "id": "r1",
                "label": "Iteration",
                "value": "1"
              }
            ]
          },
          {
            "id": "step3",
            "label": "4. Converge",
            "short": "Converge",
            "sentence": "Centroids stop moving. Clustering complete.",
            "why": "Stable boundaries achieved.",
            "active": ["c1", "c2", "pts"],
            "calloutRegion": "c2",
            "readouts": [
              {
                "id": "r1",
                "label": "Iteration",
                "value": "2"
              }
            ]
          }
        ]
      }
    ]
  }
}
